import json, re, pathlib
from collections import Counter

D = pathlib.Path('deliverable'); L = pathlib.Path('library')
files = ['clausulas.json','clausula_dados.md','nota_socia.md','QUESTIONS.md','STATUS.md']

data = json.loads((D/'clausulas.json').read_text(encoding='utf-8'))
c = Counter(e['avaliacao'] for e in data)
print('JSON OK —', len(data), 'entradas:', dict(c))

real = {p.name for p in L.glob('*.md')}
bad = []
for f in files:
    for m in sorted(set(re.findall(r'library/([A-Za-z0-9_.\-]+\.md)', (D/f).read_text(encoding='utf-8')))):
        if m not in real: bad.append((f, m))
print('citações não resolvidas:', bad if bad else 'nenhuma')

txt = ''.join((D/f).read_text(encoding='utf-8') for f in files)
print('ocorrências residuais de "sede da":', [s[:80] for s in re.findall(r'.{0,40}sede da.{0,40}', txt, re.I)])
print('CONTRATENTE (typo):', 'CONTRATENTE' in txt)

# forum wording consistency
for f in files:
    for i, line in enumerate((D/f).read_text(encoding='utf-8').splitlines(), 1):
        if 'domicílio da CONTRATANTE' in line:
            print(f'domicílio OK {f}:{i}')

# arithmetic spot re-check of the only formulas touched conceptually
t36 = 3*6900*36; print('1,57x multas:', round((t36+500000)/(48000+t36), 4))

# clausula_dados §5º blocks structure
cd = (D/'clausula_dados.md').read_text(encoding='utf-8').splitlines()
for i, line in enumerate(cd, 1):
    if line.startswith('> **Nota de contexto'):
        print(f'nota de contexto clausula_dados:{i}: linha anterior = {cd[i-2][:40]!r} (deve ser vazia e depois §5º)')
EOF

